using ll = long long;


const int N = 10005, P = 1000000007;
int n, m, a[N], g[N], f[N], inv[N];
void init() {}

void solve()
{
	cin >> n >> m;
	for (int i = 1; i <= n; ++i)
	{
		cin >> a[i];
		int v = (ll)i * a[i] % P;
		for (int j = i; j <= m; j += i) g[j] = (g[j] + v) % P;
	}
	inv[1] = 1; f[0] = 1;
	for (int i = 2; i <= m; ++i) inv[i] = P - (ll)(P / i) * inv[P % i] % P;
	for (int i = 1; i <= m; ++i)
	{
		unsigned long long s = 0;
		for (int j = 1; j <= i; ++j)
		{
			s += (unsigned long long)g[j] * f[i - j];
			if ((j & 15) == 0) s %= P;
		}
		f[i] = (s % P) * inv[i] % P;
		cout << f[i] << " \n"[i == m];
	}
}

int main()
{
#ifndef LOCAL
	freopen("bag.in", "r", stdin);
	freopen("bag.out", "w", stdout);
#endif
