#include <bits/stdc++.h>
#define endl '\n'
using namespace std;
using ll = long long;

const int N = 200005, B = 700, K = B + 5, S = (K + 15) / 16, INF = 1000000000;
struct Op { int op, l, r, q; } a[N];
struct Event { int x, p, v; bool operator < (const Event &b) const { return x < b.x; } } e[K * 2];
int n, m, v, id[N], tot, l[N], r[N], rk[N], ord[K], pos[K], val[K], tim[K];
int pre[K], suf[K], fa[K], st[K], top, k, cnt, lg[S], mn[8][S];
unsigned mask[K];
bool on[K], done[N];
ll sum[K], ans[N];

bool cmp(int x, int y) { return a[x].l < a[y].l; }
bool cmpq(int x, int y) { return a[x].q < a[y].q; }
int better(int x, int y) { return tim[x] < tim[y] ? x : y; }

void build()
{
	top = 0; pre[0] = 0; suf[k + 1] = 0; tim[0] = INF; sum[0] = 0;
	for (int i = 1; i <= k; ++i)
	{
		tim[i] = on[i] ? ord[i] : INF; fa[i] = 0;
		pre[i] = on[i] ? i : pre[i - 1];
		if (!on[i]) continue;
		int p = 0;
		while (top && tim[st[top]] > tim[i]) p = st[top--];
		if (top) fa[i] = st[top];
		if (p) fa[p] = i;
		st[++top] = i;
	}
	for (int i = k; i; --i) suf[i] = on[i] ? i : suf[i + 1];
	for (int i = 1; i <= k; ++i)
	{
		int x = pos[i];
		if (on[x]) sum[x] = sum[fa[x]] + val[x];
	}
	unsigned s = 0;
	for (int i = 1; i <= k; ++i)
	{
		int b = (i - 1) / 16, z = (i - 1) % 16;
		if (!z) s = 0;
		while (s && tim[b * 16 + 32 - __builtin_clz(s)] >= tim[i]) s &= ~(1u << (31 - __builtin_clz(s)));
		s |= 1u << z; mask[i] = s; mn[0][b] = b * 16 + __builtin_ctz(s) + 1;
	}
	int nb = (k + 15) / 16;
	for (int j = 1; (1 << j) <= nb; ++j)
		for (int i = 0; i + (1 << j) <= nb; ++i) mn[j][i] = better(mn[j - 1][i], mn[j - 1][i + (1 << (j - 1))]);
}

int query(int l, int r)
{
	int x = (l - 1) / 16, y = (r - 1) / 16;
	if (x == y) return x * 16 + __builtin_ctz(mask[r] & (~0u << ((l - 1) % 16))) + 1;
