	{
		int z = lg[y - x - 1];
		p = better(p, better(mn[z][x + 1], mn[z][y - (1 << z)]));
	}
	return p;
}

void solve()
{
	cin >> n >> m;
	for (int i = 1; i <= m; ++i)
	{
		cin >> a[i].op >> a[i].l;
		if (!a[i].op) cin >> a[i].r;
		else id[++tot] = i;
		cin >> a[i].q; v = max(v, a[i].q); r[i] = 200001;
	}
	sort(id + 1, id + tot + 1, cmp);
	for (int i = 2; i < S; ++i) lg[i] = lg[i >> 1] + 1;
