		sort(e + 1, e + cnt + 1);
		int p = 1; bool dirty = true;
		for (int j = 1; j <= tot; ++j)
		{
			int i = id[j];
			if (i <= R || done[i]) continue;
			while (p <= cnt && e[p].x <= a[i].l) { on[e[p].p] = e[p].v; ++p; dirty = true; }
