			if (w) r[i] = min(r[i], val[w]);
		}
	}
	for (int i = 1; i <= m; ++i) if (a[i].op) cout << ans[i] << endl;
}

int main()
{
#ifndef LOCAL
	freopen("xiamen.in", "r", stdin); freopen("xiamen.out", "w", stdout);
#endif
	ios::sync_with_stdio(false); cin.tie(nullptr);
