using namespace std;
using ll = long long;

const int N = 1000005;
int n, P, inv[N], h[N], t[N], phi[N], pr[N], tot;
bool vis[N];

ll norm(ll x) { x %= P; return x < 0 ? x + P : x; }

void solve()
{
	cin >> n >> P;
	inv[1] = phi[1] = 1;
	for (int i = 2; i <= n; ++i) inv[i] = P - (ll)(P / i) * inv[P % i] % P;
	for (int i = 1; i <= n; ++i)
	{
		h[i] = (h[i - 1] + inv[i]) % P;
		t[i] = (t[i - 1] + 2LL * h[i - 1] * inv[i]) % P;
		if (i > 1 && !vis[i]) { pr[++tot] = i; phi[i] = i - 1; }
		for (int j = 1; j <= tot && (ll)i * pr[j] <= n; ++j)
		{
			int v = i * pr[j]; vis[v] = true;
			if (i % pr[j] == 0) { phi[v] = phi[i] * pr[j]; break; }
			phi[v] = phi[i] * (pr[j] - 1);
		}
	}
	ll s = 0, fac = 1, b = 0;
	for (int i = 1; i < n; ++i)
		for (int j = 1; i + j <= n; ++j) s = (s + (ll)gcd(i, j) * inv[i] % P * inv[j]) % P;
	for (int i = 1; i <= n; ++i)
	{
		fac = fac * i % P;
		if (i < n) b = (b + fac * i % P * (i - 1) % P * inv[2]) % P;
	}
	ll f = norm(n - h[n] + s), c = (ll)h[n / 2] * inv[2] % P;
	ll den = (ll)inv[n] * inv[n - 1] % P;
	ll a = norm(1 + norm(c - f) * den) * inv[2] % P;
	ll z = norm(n - (ll)n * h[n] - c + f) * den % P;
	ll ans = norm(1 + norm(fac - 1) * a + b * inv[n - 2] % P * z);
	cout << ans * fac % P * fac % P << endl;
}

int main()
{
#ifndef LOCAL
	freopen("wuhan.in", "r", stdin); freopen("wuhan.out", "w", stdout);
#endif
	ios::sync_with_stdio(false); cin.tie(nullptr);
	solve(); return 0;
}

